import itertools, json

items = "FHLOPRST"
sols = []
for perm in itertools.permutations(items):
    pos = {c: i + 1 for i, c in enumerate(perm)}
    # T immediately before F or immediately after R
    if not (pos['T'] == pos['F'] - 1 or pos['T'] == pos['R'] + 1):
        continue
    # at least two compositions between F and R
    if abs(pos['F'] - pos['R']) - 1 < 2:
        continue
    # O first or fifth
    if pos['O'] not in (1, 5):
        continue
    # eighth is L or H
    if perm[7] not in ('L', 'H'):
        continue
    # P before S
    if not pos['P'] < pos['S']:
        continue
    # at least one between O and S
    if abs(pos['O'] - pos['S']) - 1 < 1:
        continue
    sols.append(pos)

# Question condition: exactly two compositions between F and O, with F before O
cond = [p for p in sols if p['F'] < p['O'] and p['O'] - p['F'] - 1 == 2]
rpos = sorted(set(p['R'] for p in cond))
names = {1: "A", 3: "B", 4: "C", 6: "D", 7: "E"}
answer = None
if len(rpos) == 1 and rpos[0] in names:
    answer = names[rpos[0]]

if answer is None:
    print("UNSUPPORTED")
else:
    print(json.dumps({
        "final_answer": answer,
        "evidence": {
            "total_valid_orders": len(sols),
            "orders_matching_condition": len(cond),
            "possible_R_positions": rpos
        }
    }))
